### Approx.fun : Zeichnet ein Saeulendiagramm einer Hyperg. Vertlng und deren Approximation durch die Binomialverteilung
 
###


Approx.fun<-function(x,Ne,Nm,n)
{
barplot(rbind(dhyper(x,Ne,Nm,n),dbinom(x,n,Ne/(Ne+Nm))),col = c(1,2),
legend=c("Hyper", "Binom"),beside=T,names=x,xlab="x",
ylab="Wahrscheinlichkeit P(x)")
abline(h = 0)
}


