konfint <- function(daten, niveau = c(0.9, 0.95, 0.99), plot = F) {
  
  # Erstmal Eckdaten bestimmen
  alpha <- 1 - niveau
  n <- length(daten)
  l <- length(niveau)
  
  # Konfidenzintervalle berechnen
  CI_minus <- mean(daten) - (qt(1 - (alpha / 2), df =  n - 1) * sqrt(var(daten) / n))
  CI_plus <- mean(daten) + (qt(1 - (alpha / 2), df =  n - 1) * sqrt(var(daten) / n))
  
  # Zu nem DF zusammenstueckeln
  dataframe <- data.frame(row.names = paste0(niveau * 100, "%"),
                          Untergrenze = CI_minus,
                          Obergrenze = CI_plus)
  
  
  # Und zurueckgeben, wenn plot = F
  if (plot == FALSE)
    return(dataframe)
  
  # Wenn plot = TRUE, dann Grafik ausgeben lassen
  if (plot == TRUE) {
    x <- seq(1045 - 600, 1045 + 600, length.out = 1000)
    plot(x, dnorm(x, 1045.37, 190.34),
         type = "l", yaxs = "i", xaxs = "i",
         xlim = c(1045 - 600, 1045 + 600), ylim = c(0, 0.0022),
         bty = "l", lwd = 2, col = "slateblue4",
         ylab="f(x)",
         main="N(1045.37, 36229.32)",
         panel.first = grid(col = "grey", lty = 1))
    
    # Paint confidence intervals
    for (i in 1:length(niveau))
      lines(c(dataframe[i, 1], dataframe[i, 2]), 
            c(5e-4, 5e-4) * (l + 1 - i) / l , type = "l", col = i + 1)
    
    # Paint mean
    abline(v = 1045.37, col = "black")
    
    # Paint legend
    legend("topleft", row.names(dataframe), title = "Konfidenzintervalle",
           col = c(seq(2, l + 1)), lty = c(rep(1, l)))
    
    # made by Stanislaus Stadlmann
    
  }
}

t.test.vis <- function(test) {
  ### Rechte Seite
  if (test$alternative == "greater") {
    x1 <- seq(test$statistic, 5, length.out = 1000)
    plot(x1, dt(x1, df = test$parameter), type = "h", col = "red",
         main = paste0("Dichte-F. der t-Verteilung mit df = ", test$parameter, " (H0)"),
         ylab = "f(x)", xlim = c(-5, 5), ylim = c(0, 0.4))
    x2 <- seq(-5, 5, length.out = 1000)
    lines(x2, dt(x2, df = test$parameter), type = "l", col = "blue")
    grid()
    text(x = 3,
         y = 0.3, labels = paste0("Seite: rechts\n",
                                  "Pruefgroesse: ", round(test$statistic, 3), "\n", 
                                  "P-Wert: ", round(test$p.value, 3)))
    
    # Ablehnungsbereiche
    df <- data.frame(niveaus = c(0.9, 0.95, 0.99),
                     quantile = qt(c(0.9, 0.95, 0.99), df = test$parameter),
                     hoehe = dt(qt(c(0.9, 0.95, 0.99), df = test$parameter), df = test$parameter) + 0.05)
    lines(df$quantile, df$hoehe, type = "h")
    text(x = df$quantile[1] + 0.2, y = df$hoehe[1] + 0.01, 
         label = expression(paste(alpha, " = ", 0.1)))
    text(x = df$quantile[2] + 0.2, y = df$hoehe[2] + 0.01, 
         label = expression(paste(alpha, " = ", 0.05)))
    text(x = df$quantile[3] + 0.2, y = df$hoehe[3] + 0.01, 
         label = expression(paste(alpha, " = ", 0.01)))
    
    ### Linke Seite
  } else if (test$alternative == "less") {
    x1 <- seq(test$statistic, -5, length.out = 1000)
    plot(x1, dt(x1, df = test$parameter), type = "h", col = "red",
         main = paste0("Dichte-F. der t-Verteilung mit df = ", test$parameter, " (H0)"),
         ylab = "f(x)", xlim = c(-5, 5), ylim = c(0, 0.4))
    x2 <- seq(-5, 5, length.out = 1000)
    lines(x2, dt(x2, df = test$parameter), type = "l", col = "blue")
    grid()
    text(x = -3,
         y = 0.3, labels = paste0("Seite: links\n",
                                  "Pruefgroesse: ", round(test$statistic, 3), "\n", 
                                  "P-Wert: ", round(test$p.value, 3)))
    
    # Ablehnungsbereiche
    df <- data.frame(niveaus = c(0.9, 0.95, 0.99),
                     quantile = qt(1 - c(0.9, 0.95, 0.99), df = test$parameter),
                     hoehe = dt(qt(1 - c(0.9, 0.95, 0.99), df = test$parameter), df = test$parameter) + 0.05)
    lines(df$quantile, df$hoehe, type = "h")
    text(x = df$quantile[1] - 0.2, y = df$hoehe[1] + 0.01, 
         label = expression(paste(alpha, " = ", 0.1)))
    text(x = df$quantile[2] - 0.2, y = df$hoehe[2] + 0.01, 
         label = expression(paste(alpha, " = ", 0.05)))
    text(x = df$quantile[3] - 0.2, y = df$hoehe[3] + 0.01, 
         label = expression(paste(alpha, " = ", 0.01)))
  } else if (test$alternative == "two.sided") {
    # P-Wert visualisieren
    x1 <- seq(-abs(test$statistic), -5, length.out = 1000)
    plot(x1, dt(x1, df = test$parameter), type = "h", col = "red",
         main = paste0("Dichte-F. der t-Verteilung mit df = ", test$parameter, " (H0)"),
         ylab = "f(x)", xlim = c(-5, 5), ylim = c(0, 0.4))
    x2 <- seq(abs(test$statistic), 5, length.out = 1000)
    lines(x2, dt(x1, df = test$parameter), type = "h", col = "red")
    
    # Verteilung visualisieren
    x3 <- seq(-5, 5, length.out = 1000)
    lines(x3, dt(x3, df = test$parameter), type = "l", col = "blue")
    grid()
    text(x = 0,
         y = 0.15, labels = paste0("Seite: zwei-seitig\n",
                                   "Pruefgroesse: ", round(test$statistic, 3), "\n", 
                                   "P-Wert: ", round(test$p.value, 3)))
    
    
    # Ablehnungsbereiche - links
    df <- data.frame(niveaus = c(0.9, 0.95, 0.99),
                     quantile = qt((1 - c(0.9, 0.95, 0.99)) / 2, df = test$parameter),
                     hoehe = dt(qt((1 - c(0.9, 0.95, 0.99)) / 2, df = test$parameter), df = test$parameter) + 0.05)
    lines(df$quantile, df$hoehe, type = "h")
    text(x = df$quantile[1] - 0.2, y = df$hoehe[1] + 0.01, 
         label = expression(paste(alpha, " = ", 0.1)))
    text(x = df$quantile[2] - 0.2, y = df$hoehe[2] + 0.01, 
         label = expression(paste(alpha, " = ", 0.05)))
    text(x = df$quantile[3] - 0.2, y = df$hoehe[3] + 0.01, 
         label = expression(paste(alpha, " = ", 0.01)))
    
    # Ablehnungsbereiche - rechts
    df <- data.frame(niveaus = c(0.9, 0.95, 0.99),
                     quantile = qt(1 - (1 - c(0.9, 0.95, 0.99)) / 2, df = test$parameter),
                     hoehe = dt(qt(1 - (1 - c(0.9, 0.95, 0.99)) / 2, df = test$parameter), df = test$parameter) + 0.05)
    lines(df$quantile, df$hoehe, type = "h")
    text(x = df$quantile[1] + 0.2, y = df$hoehe[1] + 0.01, 
         label = expression(paste(alpha, " = ", 0.1)))
    text(x = df$quantile[2] + 0.2, y = df$hoehe[2] + 0.01, 
         label = expression(paste(alpha, " = ", 0.05)))
    text(x = df$quantile[3] + 0.2, y = df$hoehe[3] + 0.01, 
         label = expression(paste(alpha, " = ", 0.01)))
  }
  # made by Stanislaus Stadlmann
}

