konfi1.fun<-function(daten=gluehall.dat,m=30,Konfidenzniveau=0.9){

w0     <- 20/2.54
h0     <- 12/2.54
PNG43D <- TRUE
seqlen <- 1000

col1.light  <- rgb(199, 209, 229, maxColorValue = 255)
col2.light  <- rgb(221, 204, 224, maxColorValue = 255)
col3.light  <- rgb(231, 202, 202, maxColorValue = 255)
col4.light  <- rgb(220, 208, 177, maxColorValue = 255)
col5.light  <- rgb(181, 212, 210, maxColorValue = 255)
col1.medium <- rgb(124, 134, 201, maxColorValue = 255)
col2.medium <- rgb(163, 130, 183, maxColorValue = 255)
col3.medium <- rgb(191, 135, 135, maxColorValue = 255)
col4.medium <- rgb(157, 138, 115, maxColorValue = 255)
col5.medium <- rgb(127, 165, 162, maxColorValue = 255)
col1 <- rgb( 45,  58, 189, maxColorValue = 255)
col2 <- rgb( 94,  45, 177, maxColorValue = 255)
col3 <- rgb(155,  71,  90, maxColorValue = 255)
col4 <- rgb(143,  99,  53, maxColorValue = 255)
col5 <- rgb( 48, 132, 131, maxColorValue = 255)
col.notice   <- "#ffff66"
col.warning  <- "#dd2222"
col.warning2 <- "#eeaab1"

croptop <- function() par(mai = par()$mai - c(0,0,0.5,0))
xlab <- function(lab, mgp1 = 3, cl = 0.9, ...){
  pm <- par()$mgp
  par(mgp = c(mgp1,pm[2:3]))
  title(xlab = lab, cex.lab = cl, ...)
  par(mgp = pm)
  rm("pm")
  }
ylab <- function(lab, mgp1 = 3, cl = 0.9, ...){
  pm <- par()$mgp
  par(mgp = c(mgp1,pm[2:3]))
  title(ylab = lab, cex.lab = cl, ...)
  par(mgp = pm)
  rm("pm")
  }
modseq <- function(x, val){
  for (i in 1: length(val)){
    x[(1:length(x))[((x-val[i])^2 == min((x-val[i])^2))][1]] <- val[i]
    }
  return(x)
  }
gridw <- function(xlo, xhi, xdels, xdell, ylo, yhi, ydels, ydell, cols =
"grey75",
                  coll = "grey50", lwds = 0.5, lwdl = 0.5, ...) {
  nxs <- ceiling((xhi - xlo)/xdels)
  nxl <- ceiling((xhi - xlo)/xdell)
  nys <- ceiling((yhi - ylo)/ydels)
  nyl <- ceiling((yhi - ylo)/ydell)
  segments(rep(xlo, nys), seq(ylo, yhi, ydels), rep(xhi, nys),
           seq(ylo, yhi, ydels), col = cols, lwd = lwds)
  segments(seq(xlo, xhi, xdels), rep(ylo, nxs), seq(xlo, xhi,
           xdels), rep(yhi, nxs), col = cols, lwd = lwds)
  segments(rep(xlo, nyl), seq(ylo, yhi, ydell), rep(xhi, nyl),
           seq(ylo, yhi, ydell), col = coll, lwd = lwdl)
  segments(seq(xlo, xhi, xdell), rep(ylo, nxl), seq(xlo, xhi,
           xdell), rep(yhi, nxl), col = coll, lwd = lwdl)
  }



### 

mu   <- mean(daten)
ki   <- matrix(NA, nrow = 20, ncol = 2)
kic  <- rep(NA, 20)
kic2 <- rep(NA, 20)

for (i in 1:20){
  test    <- sample(daten, m, replace = FALSE)
  ki[i,1] <- mean(test) - qt(1-(1-Konfidenzniveau)/2, m-1)*sd(test)/sqrt(m)
  ki[i,2] <- mean(test) + qt(1-(1-Konfidenzniveau)/2, m-1)*sd(test)/sqrt(m)
  kic[i]  <- ifelse(mu < ki[i,1] | mu > ki[i,2], col.warning, col3.medium)
  kic2[i] <- ifelse(mu < ki[i,1] | mu > ki[i,2], 4, 3)
  }

##
  par(mfrow = c(1,1), mar = c(3.2,3.7,1.3,1.3), mgp = c(2.5,0.6,0),
      lab = c(8,20,8), lend = 1, las = 1)
  plot(0, 0, xlim = c(900,1200), ylim = c(1,20), type = "n",
       xlab = "Brenndauer\n", ylab = "Stichprobe", axes = FALSE)
  gridw(xlo = 900, xhi = 1200, xdels = 20, xdell = 100, ylo = 1, yhi = 20,
        ydels = 1, ydell = 19, lwds = 0.5, lwdl = 1)
  polygon(c(900,1200,1200,900), c(1,1,20,20))
  axis(1, cex.axis = Konfidenzniveau)
  axis(2, at = 1:20, labels = 1:20, cex.axis = Konfidenzniveau)
  par(xpd=T)
  for (i in 1:20){
    lines(c(ki[i,1],ki[i,2]), c(i,i),col=kic[i], lwd = kic2[i])
    }
  par(xpd=F)
  segments(mu, Konfidenzniveau, mu, 20.4, col = col1, lwd = 3)
  text(mu, 20, expression(paste(mu," = 1045.4")), pos = 3, cex = 1.2,
xpd = NA,
       col = col1)}


