gridw<-function (xlo, xhi, xdels, xdell, ylo, yhi, ydels, ydell, cols = "grey75", 
    coll = "grey50", lwds = 0.5, lwdl = 0.5, ...)                     
{                                                                     
    nxs <- ceiling((xhi - xlo)/xdels)                                 
    nxl <- ceiling((xhi - xlo)/xdell)                                 
    nys <- ceiling((yhi - ylo)/ydels)                                 
    nyl <- ceiling((yhi - ylo)/ydell)                                 
    segments(rep(xlo, nys), seq(ylo, yhi, ydels), rep(xhi, nys),            
        seq(ylo, yhi, ydels), col = cols, lwd = lwds)                 
    segments(seq(xlo, xhi, xdels), rep(ylo, nxs), seq(xlo, xhi,            
        xdels), rep(yhi, nxs), col = cols, lwd = lwds)                
    segments(rep(xlo, nyl), seq(ylo, yhi, ydell), rep(xhi, nyl),           
        seq(ylo, yhi, ydell), col = coll, lwd = lwdl)                 
    segments(seq(xlo, xhi, xdell), rep(ylo, nxl), seq(xlo, xhi,           
        xdell), rep(yhi, nxl), col = coll, lwd = lwdl)                
}                                                                     
                                                                      
par(mfrow=c(1,1),mar=c(4,6,3,1),mgp=c(2,0.6,0),lab=c(8,3,8),xaxs="i",yaxs="i",las=1)          
                                                                      
Woche<-c("Mo","Di","Mi","Do","Fr","Sa","So")                          
xlo=0                                                                 
xhi=36                                                                
ylo=0                                                                 
yhi=12                                                                
x<-seq(xlo,xhi,length=1000)                                           
y<-seq(ylo,yhi,length=1000)                                           
                                                                      
plot(x,y,type="n",axes=F,cex.lab=1.5,cex.axis=1.2,xlab = "Tag", ylab="Anfragen in Mio.")          
axis(1,pos=ylo,at=seq(xlo,xhi,by=1),labels =c(" ",rep(Woche,5)," "), cex.axis=0.8)          
axis(2,pos=xlo,at=seq(ylo,yhi,by=1),cex.axis=1.2)                     
                                                                      
gridw(xlo=xlo, xhi=xhi, xdels=1, xdell=7, ylo=ylo, yhi=yhi, ydels=0.1, ydell=1,lwds = 0.5, lwdl = 1)          
par(xpd=T)                                                            
segments(xlo,yhi,xhi,yhi)                                             
segments(xlo,ylo,xhi,ylo)                                             
par(xpd=FALSE)                                                        
abline(h=0,v=0,lwd=2)                                                 
abline(h=0,v=0,lwd=2)                                                 
par(mfrow=c(1,1),mar=c(4,6,3,1),mgp=c(2,0.6,0),lab=c(8,3,8),xaxs="i",yaxs="i",las=1)          
                                                                 
lines(1:35,leo,type="o",lwd=2) }


################
### muenze.fun
### R-Funktion / Pfad der relativen Haeufigkeiten beim Muenzwurf
################

coin<-function (n, prob = 0.5) 
{
  stichpr <- sample(c(0, 1), size = n, repl = T, prob = c(1 - prob, prob))
  plot(1:n, cumsum(stichpr)/1:n, type = "l", ylim = c(0, 1), xlim=c(1,n),
       main = "Pfad der relativen Haeufigkeiten", xlab = "Anzahl Wuerfe", 
       ylab = "relative Haeufigkeit", xaxs="i",yaxs="i", col = 2, lwd = 2)
  grid (NULL,NULL, lty = 1, col = "grey")
  abline(h=0)
  abline(h=1)
  abline(h = prob,col="blue3",lwd=3)
  abline(v=n)
  abline(v=1)
  par(xpd=T)
  lines(1:n, cumsum(stichpr)/1:n,col=2,lwd=2)
  par(xpd=F)
  legend("bottom",c("Pfad der relativen Haeufigkeiten","theoretische Wahrscheinlichkeit"),col=c("red","blue3"),lty=c(1,1))
}


