wuerfel.fun<-function(n1,n2)

{
rel.hf1<-table(sample(c(1,2,3,4,5,6),n1,replace=T))/n1
rel.hf2<-table(sample(c(1,2,3,4,5,6),n2,replace=T))/n2

par(mfrow=c(2,1))
barplot(rel.hf1,ylim=c(0,max(rel.hf1)),xlab="Augenzahl",ylab="relative Haeufigkeit",main="kleinere Stichprobe")
abline(h=1/6,col=2,lwd=2)
barplot(rel.hf2,ylim=c(0,max(rel.hf1)),xlab="Augenzahl",ylab="relative Haeufigkeit",main="groessere Stichprobe")
abline(h=1/6,col=2,lwd=2)
}


Wuerfelsumme<-function(n){
	Wurf1<-sample(c(1,2,3,4,5,6),n,replace=T)
	Wurf2<-sample(c(1,2,3,4,5,6),n,replace=T)
	Summe<-Wurf1 + Wurf2
	plot(c(0, n), c(7, 7), col = "red", type = "l", main = "Pfad des Mittelwertes", ylab = "mittlere Wuerfelsumme", xlab = "Wuerfe")
	lines(1:n, cumsum(Summe) / 1:n)}

