verteilungsfunktion<-function(x,Px){
  Fx<-c(0,cumsum(Px))
  Verteilung<-stepfun(x,Fx)
  plot(Verteilung,verticals=F,pch=16,lwd=1,main="Graph der Verteilungsfunktion",ylab="F(x)",col="red",xaxs="i",yaxs="i",xlim=c(min(x)-1,max(x)+1.5),ylim=c(0,1),panel.first=c(abline(h=seq(0,1,0.05),v=seq(min(x)-1,max(x)+1.5,0.5), lwd=0.5, col="grey"),
                                                                                                                                                                              abline(h=seq(0,1,0.1), v=seq(min(x)-1,max(x)+1.5,1), lwd=1, col="gray40")))
  par(xpd=T)
  points(x,Fx[-1],pch=16,col="red")
  par(xpd=F)
}

approx<-function(n,pi){
x<-0:n
z<-seq(-0.5,max(x)+1.5,length=n+100)
Fx<-pbinom(x,n,pi)
Gx<-pnorm(z,n*pi,sqrt(n*pi*(1-pi)))
Hx<-pnorm(z+0.5,n*pi,sqrt(n*pi*(1-pi)))
plot(z,Gx,type="l",lwd=2,xlim=c(-0.5,max(x)+1.5),col="slateblue4",ylab="F(x)",xlab="x",main="Verteilungsfunktion Aufgabe 2 g)",lend=1,ylim=c(0,1),yaxs="i",xaxs="i",bty="l",panel.first=grid(lty=1,col="grey"))
lines(z,Hx,type="l",xaxt="n",lwd=2,xlim=c(-0.5,max(x)+1.5),col="red",ylab="F(x)",xlab="x",main="Verteilungsfunktion Aufgabe 2 g)",lend=1,ylim=c(0,1),yaxs="i",xaxs="i")
par(xpd=T)
x0<-c(-0.5,x)
y0<-c(0,pbinom(x,n,pi))
x1<-c(x,max(x)+1.5)
y1<-c(0,pbinom(x,n,pi))
segments(x0,y0,x1,y1,col="turquoise3",lwd=2,lend=1)
points(x,Fx,pch=16)
par(xpd=F)
if(pi<=0.6){legend('bottomright',c(expression(B(n,pi)),expression(N(mu,sigma^2)),expression(paste(N(mu,sigma^2)," mit Korrektur"))),col=c("turquoise3","slateblue4","red"),lty=c(1,1,1))}
if(pi>0.6){legend('topleft',c(expression(B(n,pi)),expression(N(mu,sigma^2)),expression(paste(N(mu,sigma^2)," mit Korrektur"))),col=c("turquoise3","slateblue4","red"),lty=c(1,1,1))}
}

fehler<-function(n,width){
  a<-rnorm(n)
  b<-seq(-5,5,length=1000)
  hist(a,breaks=seq(-5,5,width),freq=F,ylim=c(0,0.5),xlim=c(-5,5),xaxs="i",yaxs="i",col="lightgreen",xlab="x",ylab="rel. Haeufigkeit/Klassenbreite",main = paste0("Histogramm mit n = ", n, " und KB = ", width))
  grid(col="grey",lty=1)
  hist(a,add=TRUE,breaks=seq(-5,5,width),freq=F,ylim=c(0,0.5),xaxs="i",yaxs="i",col="lightgreen")
  lines(b,dnorm(b),col="dodgerblue4",lwd=2)
}


